<?php /* The forge's retrospective ledger: each hour (and week), its numbers, the rule findings, the agent's note and its proposals. Nothing here changes anything: a proposal is acted on by a person. */ ?>
<div class="vl-wrap">
  <?php if ($inbox['decide'] || $inbox['review']): ?><div class="vl-card vl-inbox"><b>Waiting on you:</b> <?= (int) $inbox['decide'] ?> proposal<?= $inbox['decide'] === 1 ? '' : 's' ?> to decide · <?= (int) $inbox['review'] ?> change<?= $inbox['review'] === 1 ? '' : 's' ?> to review. Approve builds the change on its own branch; nothing reaches the live forge until you merge it.</div><?php endif; ?>
  <div class="vl-head"><h1 class="vl-h1">The forge, hour by hour</h1><p class="vl-lede">Every hour the forge measures itself (runs, cost, art jobs, keeps), applies its rules, and, when something happened, has a read-only agent write a note and at most three proposals. The measures and findings are deterministic; the note and proposals are the agent's. Nothing changes until someone says so.</p></div>
  <?php if (!$entries): ?><p class="vl-muted">No hours recorded yet: <code>php scripts/forge-retro.php</code> records the last full hour; cron runs it at five past every hour.</p><?php endif; ?>
  <?php foreach ($entries as $e): $m = $e['measures']; $fs = array_filter((array) $e['findings'], fn($f) => $f['rule'] !== 'quiet'); $quiet = !$fs && empty($e['proposals']) && !$m['runs']['build'] && !$m['runs']['art'] && !$m['art']['jobs']; ?>
  <details class="vl-card vl-retro<?= $quiet ? ' quiet' : '' ?>" <?= $e === $entries[0] || $e['kind'] === 'week' ? 'open' : '' ?>>
    <summary><b><?= $e['kind'] === 'week' ? 'The week to ' : '' ?><?= h(date('D j M H:00', strtotime($e['at']))) ?></b>
      <span class="vl-muted"> · <?= (int) $m['runs']['build'] ?> build + <?= (int) $m['runs']['art'] ?> art runs · $<?= number_format((float) $m['cost']['total'], 2) ?> · <?= (int) $m['art']['jobs'] ?> art jobs · <?= (int) $m['keeps'] ?> kept<?= $m['cost_per_keep'] !== null ? ' · $' . h($m['cost_per_keep']) . ' per keep' : '' ?><?= $fs ? ' · ' . count($fs) . ' finding' . (count($fs) === 1 ? '' : 's') : '' ?><?= !empty($e['proposals']) ? ' · ' . count($e['proposals']) . ' proposal' . (count($e['proposals']) === 1 ? '' : 's') : '' ?><?= $quiet ? ' · quiet' : '' ?></span></summary>
    <div class="vl-retro-body">
      <?php if (!empty($e['note'])): ?><p><?= nl2br(h($e['note'])) ?></p><?php endif; ?>
      <?php if ($fs): ?><h3 class="vl-h2">Findings</h3><ul><?php foreach ($fs as $f): ?><li><span class="vl-pill <?= h($f['severity']) ?>"><?= h($f['severity']) ?></span> <?= h($f['text']) ?><?php if (!empty($f['evidence'])): ?><div class="vl-muted small"><?= h(implode(' · ', array_slice((array) $f['evidence'], 0, 6))) ?></div><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
      <?php if (!empty($e['proposals'])): ?><h3 class="vl-h2">Proposals</h3><ol><?php foreach ($e['proposals'] as $pi => $p): $pid = basename((string) ($e['file'] ?? ''), '.json') . '#' . $pi; $st = $states[$pid] ?? []; $status = $st['status'] ?? ($p['status'] ?? 'open'); ?><li id="<?= h($pid) ?>" data-pid="<?= h($pid) ?>"><b><?= h($p['title']) ?></b> <span class="vl-muted">· <?= h($p['kind']) ?> · <code><?= h($p['file']) ?></code><?= empty($p['file_exists']) && !empty($p['file']) ? ' <span class="vl-pill high">file not found</span>' : '' ?><?= !empty($p['from']) ? ' · from ' . h(date('D H:00', strtotime($p['from']))) : '' ?><?php if (($p['status'] ?? 'open') !== 'open'): ?> <span class="vl-pill <?= str_starts_with((string) $p['status'], 'built') ? 'low' : 'medium' ?>"><?= h($p['status']) ?></span><?php endif; ?></span><div><?= nl2br(h($p['change'])) ?></div><div class="vl-muted small">evidence: <?= h($p['evidence']) ?><?= !empty($p['measure']) ? ' · measure: ' . h($p['measure']) : '' ?><?= !empty($p['rule']) && $p['rule'] !== 'other' ? ' · targets: ' . h($p['rule']) : '' ?></div>
        <?php if ($e['kind'] === 'hour'): ?><div class="vl-gate">
          <?php if ($status === 'open' || $status === 'later'): ?><button class="btn btn-sm btn-primary" data-act="approve">Approve &amp; build</button> <button class="btn btn-sm btn-outline-secondary" data-act="later">Later</button> <button class="btn btn-sm btn-outline-danger" data-act="decline">Decline…</button>
          <?php elseif ($status === 'building'): ?><span class="vl-pill medium">building on its own branch…</span>
          <?php elseif ($status === 'built'): ?><div class="small"><b>Built:</b> <?= h($st['summary'] ?? '') ?><?php if (!empty($st['cost'])): ?> <span class="vl-muted">($<?= h(number_format((float) $st['cost'], 2)) ?>)</span><?php endif; ?></div><details><summary class="small">the diff (<?= h(count((array) ($st['files'] ?? []))) ?> file<?= count((array) ($st['files'] ?? [])) === 1 ? '' : 's' ?>: <?= h(implode(', ', (array) ($st['files'] ?? []))) ?>)</summary><pre class="vl-json vl-diff" data-diff></pre></details><button class="btn btn-sm btn-primary" data-act="merge">Merge into the live forge</button> <button class="btn btn-sm btn-outline-danger" data-act="reject">Reject…</button>
          <?php elseif ($status === 'merged'): ?><span class="vl-pill low">merged <?= h(date('D H:i', strtotime((string) ($st['merged'] ?? 'now')))) ?><?= empty($st['pushed']) ? ' (not pushed)' : '' ?></span><?php if (!empty($st['verdict'])): ?> <span class="vl-pill <?= str_starts_with($st['verdict'], 'helped') ? 'low' : (str_starts_with($st['verdict'], 'worse') ? 'high' : 'medium') ?>"><?= h($st['verdict']) ?></span><?php else: ?> <span class="vl-muted small">its effect is measured a day after the merge</span><?php endif; ?>
          <?php elseif ($status === 'failed'): ?><span class="vl-pill high">failed</span> <span class="small"><?= h($st['error'] ?? '') ?></span> <button class="btn btn-sm btn-outline-secondary" data-act="approve">Try again</button>
          <?php else: ?><span class="vl-pill medium"><?= h($status) ?></span><?= !empty($st['note']) ? ' <span class="vl-muted small">' . h($st['note']) . '</span>' : '' ?><?php if (in_array($status, ['declined', 'rejected'], true)): ?> <button class="btn btn-sm btn-link" data-act="later">reopen</button><?php endif; ?>
          <?php endif; ?><span class="vl-gate-msg small"></span></div><?php endif; ?>
        </li><?php endforeach; ?></ol><?php endif; ?>
      <details class="vl-muted small"><summary>the numbers</summary><pre class="vl-json"><?= h(json_encode($m, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></pre><?php if (!empty($e['agent'])): ?><div>agent: <?= $e['agent']['ok'] ? 'ok' : 'failed' ?> · $<?= h(number_format((float) ($e['agent']['cost'] ?? 0), 3)) ?><?= !empty($e['agent']['error']) ? ' · ' . h($e['agent']['error']) : '' ?></div><?php endif; ?></details>
    </div>
  </details>
  <?php endforeach; ?>
</div>
<script>
// the two gates: decide on a proposal; accept or reject a built change
document.addEventListener('click', async ev => {
  const b = ev.target.closest('[data-act]'); if (!b) return; const li = b.closest('[data-pid]'), id = li.dataset.pid, act = b.dataset.act, msg = li.querySelector('.vl-gate-msg');
  let note = '', url = '/forge/improvedecide', body = { id };
  if (act === 'decline' || act === 'reject') { note = prompt(act === 'decline' ? 'Why decline it? (the retrospective learns from this)' : 'Why reject the change? (the retrospective learns from this)', ''); if (note === null) return; }
  if (act === 'approve') { note = prompt('Approve and build it. Anything the improver should know? (optional)', '') ; if (note === null) return; }
  if (act === 'merge' && !confirm('Merge this change into the live forge? It is checked, the site is smoke-tested, and it is rolled back by itself if anything fails.')) return;
  if (act === 'merge') url = '/forge/improvemerge'; else if (act === 'reject') url = '/forge/improvereject'; else body.decision = act; body.note = note;
  b.disabled = true; msg.textContent = act === 'merge' ? ' merging and smoke-testing…' : ' …';
  try { const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': <?= json_encode(csrf_token()) ?>, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.success === false) throw new Error(j.message || j.error || r.status); location.hash = id; location.reload(); }
  catch (e) { msg.textContent = ' ' + e.message; b.disabled = false; }
});
// a built change's diff is fetched when its fold opens
for (const d of document.querySelectorAll('.vl-gate details')) d.addEventListener('toggle', async () => { const pre = d.querySelector('[data-diff]'); if (!d.open || pre.textContent) return; const id = d.closest('[data-pid]').dataset.pid; pre.textContent = await (await fetch('/forge/improvediff?id=' + encodeURIComponent(id))).text() || '(no diff)'; });
</script>
<style>
.vl-inbox { border-color: #e07700; margin-bottom: 12px; } .vl-gate { margin-top: 6px; display: flex; gap: 6px; flex-wrap: wrap; align-items: center; } .vl-gate details { width: 100%; } .vl-diff { max-height: 420px; overflow: auto; font-size: .78rem; white-space: pre; }
.vl-retro { margin-bottom: 10px; } .vl-retro summary { cursor: pointer; } .vl-retro.quiet { opacity: .6; } .vl-retro-body { padding-top: 8px; display: grid; gap: 8px; } .vl-retro-body ul, .vl-retro-body ol { margin: 0; padding-left: 20px; } .vl-retro-body li { margin: 4px 0; }
.vl-pill.high { background: #4a1a1a; color: #ff9b9b; } .vl-pill.medium { background: #4a3a10; color: #ffd166; } .vl-pill.low { background: #1a2a3a; color: #9ad0ff; } .small { font-size: .82rem; }
</style>
